namespace sv_9702f39c69ce4323af0c85034fbf23ff;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@inject CascadingValueSource<ThemeInfo> ThemeSource

<span class="theme-indicator" style="color: @Theme?.AccentColor;">
    @GetThemeIcon() @Theme?.Theme
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetThemeIcon() => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

@inject CascadingValueSource<ThemeInfo> ThemeSource

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        style="border-color: @Theme?.AccentColor; color: @Theme?.AccentColor;">
    @GetThemeIcon() Theme
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetThemeIcon() => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };

    private async Task CycleTheme()
    {
        if (Theme is null) return;

        var next = Theme.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };

        await ThemeSource.NotifyChangedAsync(
            new ThemeInfo { Theme = next, AccentColor = Theme.AccentColor });
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 400px; border-color: @Theme?.AccentColor;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            var isActive = Theme?.Theme == t;
            <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SetTheme(t)">
                @t
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <input type="color" class="form-control form-control-color mb-3"
           value="@(Theme?.AccentColor ?? "#0d6efd")"
           @onchange="SetAccentColor" />

    <p style="color: @Theme?.AccentColor;">
        Preview: Current theme is <strong>@Theme?.Theme</strong>
        with accent <strong>@Theme?.AccentColor</strong>.
    </p>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task SetTheme(Theme theme)
    {
        await ThemeSource.NotifyChangedAsync(
            new ThemeInfo { Theme = theme, AccentColor = Theme?.AccentColor ?? "#0d6efd" });
    }

    private async Task SetAccentColor(ChangeEventArgs e)
    {
        var color = e.Value?.ToString() ?? "#0d6efd";
        await ThemeSource.NotifyChangedAsync(
            new ThemeInfo { Theme = Theme?.Theme ?? Theme.Light, AccentColor = color });
    }
}

